import json

allowed_labels = {"billing", "technical", "general"}
prompt = "Classify the ticket. Return JSON with one label: billing, technical, or general."
response_fixture = '{"label": "billing"}'
parsed = json.loads(response_fixture)
if not isinstance(parsed, dict) or set(parsed) != {"label"}:
    raise ValueError("Invalid response shape")
if parsed["label"] not in allowed_labels:
    raise ValueError("Unsupported label")
print("Validated fixture label:", parsed["label"])

inventory = {"P001": {"name": "Notebook", "stock": 12}}

def dispatch(call):
    if call.get("name") != "get_stock":
        raise ValueError("Unsupported tool")
    arguments = call.get("arguments")
    if not isinstance(arguments, dict) or set(arguments) != {"product_id"}:
        raise ValueError("Invalid arguments")
    product_id = arguments["product_id"]
    if not isinstance(product_id, str) or not product_id.strip():
        raise ValueError("A product ID is required")
    return inventory.get(product_id, {"error": "Product not found"})

proposal = {"name": "get_stock", "arguments": {"product_id": "P001"}}
print(dispatch(proposal))

import math

def cosine(left, right):
    if len(left) != len(right):
        raise ValueError("Dimensions must match")
    norm_left = math.sqrt(sum(value * value for value in left))
    norm_right = math.sqrt(sum(value * value for value in right))
    if norm_left == 0 or norm_right == 0:
        raise ValueError("Zero vectors have no cosine similarity")
    return sum(a * b for a, b in zip(left, right)) / (norm_left * norm_right)

query = [0.8, 0.2]
illustrative_document = [1.0, 0.0]
print(f"Illustrative similarity: {cosine(query, illustrative_document):.3f}")
